// The update log (updates.ts) in every language: updates 29 to 33. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES3: Readonly<Record<string, Row>> = {
  "The Faith update: the Order of the Dawn": ["信仰アップデート：Order of the Dawn", "신앙 업데이트: Order of the Dawn", "信仰更新：Order of the Dawn", "信仰更新：Order of the Dawn", "Bản cập nhật Đức tin: Order of the Dawn", "Pembaruan Iman: Order of the Dawn", "อัปเดตศรัทธา: Order of the Dawn", "İnanç güncellemesi: Order of the Dawn", "La actualización de la Fe: la Order of the Dawn", "A atualização da Fé: a Order of the Dawn", "Обновление Веры: Order of the Dawn", "Оновлення Віри: Order of the Dawn"],
  "Prayer is now Faith. Your levels, XP and prayers carry over; faith is what your prayers draw on, and altars restore it.": ["祈りは「信仰」になりました。レベル、経験値、祈りはそのまま引き継がれます。祈りは信仰を消費し、祭壇で回復します。", "기도가 이제 신앙이 되었습니다. 레벨, 경험치, 기도는 그대로 이어집니다. 기도는 신앙을 소모하고, 제단이 그것을 회복시킵니다.", "祈祷现在改名为信仰。你的等级、经验和祷文都会保留；祷文消耗信仰，祭坛可以恢复信仰。", "祈禱現在改名為信仰。你的等級、經驗和禱文都會保留；禱文消耗信仰，祭壇可以恢復信仰。", "Cầu nguyện giờ là Đức tin. Cấp, XP và các lời cầu nguyện của bạn được giữ lại; lời cầu nguyện tiêu hao đức tin, và bàn thờ hồi phục nó.", "Doa kini menjadi Iman. Level, XP, dan doamu tetap; doa menggunakan iman, dan altar memulihkannya.", "การสวดภาวนาตอนนี้เป็นศรัทธา เลเวล XP และบทสวดของคุณยังอยู่ บทสวดใช้ศรัทธา และแท่นบูชาฟื้นฟูมัน", "Dua artık İnanç. Seviyelerin, XP'n ve duaların aktarılıyor; dualar inancı tüketir, sunaklar onu yeniler.", "La Oración pasa a ser Fe. Tus niveles, XP y plegarias se conservan; las plegarias gastan fe y los altares la restauran.", "Oração agora é Fé. Seus níveis, XP e preces continuam; as preces gastam fé, e os altares a restauram.", "Молитва теперь называется Верой. Уровни, опыт и молитвы сохраняются; молитвы тратят веру, а алтари её восстанавливают.", "Молитва тепер називається Вірою. Рівні, досвід і молитви зберігаються; молитви витрачають віру, а вівтарі її відновлюють."],
  "The Order of the Dawn keeps Dawnhold, a chapterhouse on a terrace above the sea east of Highcairn (a cobbled causeway runs there through the ridge): Grandmaster Aldric, Sister Maren the chaplain, Quartermaster Bram and the knights of the Dawn in white and gold.": ["Order of the Dawn はハイケアンの東、海を見下ろす段丘に立つ参事会館ドーンホールドを守っています（尾根を抜ける石畳の土手道で行けます）：総長アルドリック、チャプレンのシスター・マーレン、補給係ブラム、そして白と金をまとった暁の騎士たち。", "Order of the Dawn은 하이케언 동쪽, 바다 위 단구에 있는 참사회관 돈홀드를 지킵니다(능선을 지나는 자갈 둑길로 갑니다): 그랜드마스터 앨드릭, 사제 마렌 수녀, 보급관 브램, 그리고 흰색과 금색의 여명 기사들.", "Order of the Dawn 驻守晨堡，一座位于高冢以东、俯瞰大海的台地上的会堂（一条鹅卵石堤道穿过山脊通往那里）：大团长奥尔德里克、随军牧师玛伦修女、军需官布拉姆，以及身着白金的黎明骑士。", "Order of the Dawn 駐守晨堡，一座位於高塚以東、俯瞰大海的台地上的會堂（一條鵝卵石堤道穿過山脊通往那裡）：大團長奧爾德里克、隨軍牧師瑪倫修女、軍需官布拉姆，以及身著白金的黎明騎士。", "Order of the Dawn giữ Dawnhold, một hội đường trên bậc thềm nhìn ra biển phía đông Highcairn (một con đường đá cuội xuyên qua sống núi dẫn đến đó): Đại sư Aldric, Sơ Maren tuyên úy, Quân nhu Bram và các hiệp sĩ Bình Minh trong sắc trắng và vàng.", "Order of the Dawn menjaga Dawnhold, sebuah balai ordo di teras di atas laut timur Highcairn (jalan berbatu menembus punggung bukit ke sana): Grandmaster Aldric, Suster Maren sang pendeta, Juru Perbekalan Bram, dan para ksatria Fajar berbaju putih dan emas.", "Order of the Dawn ดูแลดอว์นโฮลด์ หอประชุมบนลานเหนือทะเลทางตะวันออกของไฮแคร์น (ทางหินกรวดตัดผ่านสันเขาไปถึง): ปรมาจารย์อัลดริก ซิสเตอร์มาเรนนักบวชประจำ ผู้จัดหาเสบียงแบรม และอัศวินรุ่งอรุณในชุดขาวทอง", "Order of the Dawn, Highcairn'in doğusunda denize bakan bir taraçadaki tarikat evi Dawnhold'u korur (sırttan geçen arnavut kaldırımlı bir yol oraya gider): Büyük Üstat Aldric, papaz Rahibe Maren, Levazımcı Bram ve beyazlı altınlı Şafak şövalyeleri.", "La Order of the Dawn custodia Dawnhold, una casa capitular en una terraza sobre el mar al este de Highcairn (una calzada empedrada cruza la cresta hasta allí): el Gran maestre Aldric, la hermana Maren, capellana, el Intendente Bram y los caballeros del Alba de blanco y oro.", "A Order of the Dawn guarda Dawnhold, uma casa capitular num terraço sobre o mar a leste de Highcairn (uma calçada de pedra atravessa a serra até lá): o Grão-mestre Aldric, a Irmã Maren, capelã, o Intendente Bram e os cavaleiros da Aurora de branco e dourado.", "Order of the Dawn хранит Даунхолд — капитул на террасе над морем к востоку от Хайкэрна (туда через хребет ведёт мощёная дамба): Великий магистр Олдрик, капеллан сестра Марен, интендант Брэм и рыцари Зари в белом и золотом.", "Order of the Dawn береже Даунголд — капітул на терасі над морем на схід від Гайкерна (туди через хребет веде брукована гребля): Великий магістр Олдрік, капелан сестра Марен, інтендант Брем і лицарі Світанку в білому й золотому."],
  "New quest, The Dawn Vigil (Novice, Faith 10): offer bones on the Dawnhold chapel altar and become a squire of the Order. Reward: a Dawnsteel sword, 1,500 Faith XP and the Order Armoury.": ["新クエスト「夜明けの寝ずの番」（初級、信仰10）：ドーンホールドの礼拝堂の祭壇に骨を捧げ、騎士団の従者になろう。報酬：暁鋼の剣、信仰経験値1,500、Order Armoury。", "새 퀘스트 「새벽의 철야」(초급, 신앙 10): 돈홀드 예배당 제단에 뼈를 바치고 기사단의 종자가 되세요. 보상: 여명강철 검, 신앙 경험치 1,500, Order Armoury.", "新任务「黎明守夜」（新手，信仰 10）：在晨堡礼拜堂的祭坛上供奉骨头，成为骑士团的侍从。奖励：晨钢剑、1,500 信仰经验和 Order Armoury。", "新任務「黎明守夜」（新手，信仰 10）：在晨堡禮拜堂的祭壇上供奉骨頭，成為騎士團的侍從。獎勵：晨鋼劍、1,500 信仰經驗和 Order Armoury。", "Nhiệm vụ mới, Canh thức Bình minh (Tập sự, Đức tin 10): dâng xương trên bàn thờ nhà nguyện Dawnhold và trở thành giám mã của Dòng. Phần thưởng: một Kiếm thép bình minh, 1.500 XP Đức tin và Order Armoury.", "Misi baru, Jaga Fajar (Pemula, Iman 10): persembahkan tulang di altar kapel Dawnhold dan jadilah pengawal Ordo. Hadiah: Pedang baja fajar, 1.500 XP Iman, dan Order Armoury.", "เควสต์ใหม่ เฝ้ารุ่งอรุณ (มือใหม่ ศรัทธา 10): ถวายกระดูกบนแท่นบูชาในโบสถ์ดอว์นโฮลด์และเป็นอัศวินฝึกหัดของภาคี รางวัล: ดาบเหล็กรุ่งอรุณ XP ศรัทธา 1,500 และ Order Armoury", "Yeni görev, Şafak Nöbeti (Acemi, İnanç 10): Dawnhold şapelinin sunağına kemik sun ve Tarikat'ın silahtarı ol. Ödül: bir Şafak çeliği kılıç, 1.500 İnanç XP'si ve Order Armoury.", "Nueva misión, La vigilia del Alba (Novato, Fe 10): ofrece huesos en el altar de la capilla de Dawnhold y hazte escudero de la Orden. Recompensa: una Espada de acero del alba, 1.500 de XP de Fe y la Order Armoury.", "Nova missão, A Vigília da Aurora (Novato, Fé 10): ofereça ossos no altar da capela de Dawnhold e torne-se escudeiro da Ordem. Recompensa: uma Espada de aço-da-aurora, 1.500 de XP de Fé e a Order Armoury.", "Новый квест «Бдение Рассвета» (Новичок, Вера 10): принесите кости к алтарю часовни Даунхолда и станьте оруженосцем Ордена. Награда: меч из стали зари, 1500 опыта Веры и Order Armoury.", "Новий квест «Чування Світанку» (Новачок, Віра 10): принесіть кістки до вівтаря каплиці Даунголда й станьте зброєносцем Ордену. Нагорода: меч зі сталі світанку, 1500 досвіду Віри та Order Armoury."],
  "New quest, Light in the Greyhorn (Intermediate, Faith 30): win the shards of the Order's broken relic back from the stone golems of the Greyhorn mine and bless them on the altar. Reward: the Cape of the Dawn, 5,000 Faith XP, 2,000 Defence XP and the Order's finest weapons.": ["新クエスト「グレイホーンの灯」（中級、信仰30）：グレイホーン鉱山の石のゴーレムから騎士団の壊れた聖遺物の破片を取り戻し、祭壇で祝福しよう。報酬：暁のマント、信仰経験値5,000、防御経験値2,000、騎士団の最上の武器。", "새 퀘스트 「그레이혼의 등불」(중급, 신앙 30): 그레이혼 광산의 돌 골렘에게서 기사단의 부서진 성유물 조각을 되찾아 제단에서 축복하세요. 보상: 여명의 망토, 신앙 경험치 5,000, 방어 경험치 2,000, 기사단 최고의 무기.", "新任务「灰角山之光」（中级，信仰 30）：从灰角矿的石魔像手中夺回骑士团破碎圣物的碎片，并在祭坛上为其祝福。奖励：黎明披风、5,000 信仰经验、2,000 防御经验以及骑士团最好的武器。", "新任務「灰角山之光」（中級，信仰 30）：從灰角礦的石魔像手中奪回騎士團破碎聖物的碎片，並在祭壇上為其祝福。獎勵：黎明披風、5,000 信仰經驗、2,000 防禦經驗以及騎士團最好的武器。", "Nhiệm vụ mới, Ánh sáng ở Greyhorn (Trung cấp, Đức tin 30): giành lại các mảnh thánh tích vỡ của Dòng từ những golem đá ở mỏ Greyhorn và ban phước cho chúng trên bàn thờ. Phần thưởng: Áo choàng Bình Minh, 5.000 XP Đức tin, 2.000 XP Phòng thủ và những vũ khí tốt nhất của Dòng.", "Misi baru, Cahaya di Greyhorn (Menengah, Iman 30): rebut kembali pecahan relik Ordo yang rusak dari golem batu di tambang Greyhorn dan berkati di altar. Hadiah: Mantel Fajar, 5.000 XP Iman, 2.000 XP Pertahanan, dan senjata terbaik Ordo.", "เควสต์ใหม่ แสงในเกรย์ฮอร์น (ปานกลาง ศรัทธา 30): ชิงเศษพระธาตุที่แตกของภาคีคืนจากโกเลมหินในเหมืองเกรย์ฮอร์นแล้วอวยพรบนแท่นบูชา รางวัล: ผ้าคลุมรุ่งอรุณ XP ศรัทธา 5,000 XP ป้องกัน 2,000 และอาวุธชั้นยอดของภาคี", "Yeni görev, Greyhorn'daki Işık (Orta, İnanç 30): Tarikat'ın kırık kutsal emanetinin parçalarını Greyhorn madenindeki taş golemlerden geri al ve sunakta kutsa. Ödül: Şafağın pelerini, 5.000 İnanç XP'si, 2.000 Savunma XP'si ve Tarikat'ın en iyi silahları.", "Nueva misión, Luz en el Greyhorn (Intermedio, Fe 30): recupera los fragmentos de la reliquia rota de la Orden de los gólems de piedra de la mina Greyhorn y bendícelos en el altar. Recompensa: la Capa del Alba, 5.000 de XP de Fe, 2.000 de XP de Defensa y las mejores armas de la Orden.", "Nova missão, Luz no Greyhorn (Intermediário, Fé 30): recupere os fragmentos da relíquia quebrada da Ordem dos golens de pedra da mina Greyhorn e abençoe-os no altar. Recompensa: a Capa da Aurora, 5.000 de XP de Fé, 2.000 de XP de Defesa e as melhores armas da Ordem.", "Новый квест «Свет в Грейхорне» (Средний, Вера 30): отбейте осколки сломанной реликвии Ордена у каменных големов рудника Грейхорна и благословите их на алтаре. Награда: Плащ Зари, 5000 опыта Веры, 2000 опыта Защиты и лучшее оружие Ордена.", "Новий квест «Світло в Грейгорні» (Середній, Віра 30): відбийте уламки зламаної реліквії Ордену в кам'яних големів копальні Грейгорна й благословіть їх на вівтарі. Нагорода: Плащ Світанку, 5000 досвіду Віри, 2000 досвіду Захисту та найкраща зброя Ордену."],
  "Faith weapons, which need Faith as well as Attack or Magic: the Dawnsteel sword, the Vigil spear, the Radiant greatsword and the Sunforged warhammer, and the Acolyte's staff, the Dawn staff and the Staff of the First Light. Every hit you land with one gives a little Faith XP, and they hurt the undead (skeletons, shades and the Hollow) harder.": ["攻撃または魔法に加えて信仰も必要な信仰の武器：暁鋼の剣、不寝番の槍、光輝の大剣、陽鍛えのウォーハンマー、そして侍祭の杖、暁の杖、始まりの光の杖。命中するたびに信仰経験値が少し入り、アンデッド（骸骨、影、虚ろなるもの）により大きなダメージを与えます。", "공격이나 마법에 더해 신앙도 필요한 신앙 무기: 여명강철 검, 철야의 창, 광휘의 대검, 태양단조 전쟁망치, 그리고 시종의 지팡이, 여명의 지팡이, 태초의 빛 지팡이. 명중할 때마다 신앙 경험치가 조금 들어오고, 언데드(해골, 망령, 공허)에게 더 큰 피해를 줍니다.", "信仰武器，除攻击或魔法外还需要信仰：晨钢剑、守夜长矛、辉光巨剑和日铸战锤，以及侍僧法杖、黎明法杖和初光法杖。每次命中都会获得少量信仰经验，并且对亡灵（骷髅、幽影和虚空）伤害更高。", "信仰武器，除攻擊或魔法外還需要信仰：晨鋼劍、守夜長矛、輝光巨劍和日鑄戰錘，以及侍僧法杖、黎明法杖和初光法杖。每次命中都會獲得少量信仰經驗，並且對亡靈（骷髏、幽影和虛空）傷害更高。", "Vũ khí Đức tin, cần Đức tin cùng với Tấn công hoặc Phép thuật: Kiếm thép bình minh, Giáo canh thức, Đại kiếm rạng ngời và Búa chiến rèn bằng mặt trời, cùng Gậy thầy giúp lễ, Gậy Bình Minh và Gậy Ánh Sáng Đầu Tiên. Mỗi đòn trúng cho một ít XP Đức tin, và chúng gây sát thương mạnh hơn lên xác sống (bộ xương, bóng ma và Hư không).", "Senjata Iman, yang butuh Iman selain Serang atau Sihir: Pedang baja fajar, Tombak jaga, Pedang besar bercahaya, dan Palu perang tempaan surya, serta Tongkat pembantu imam, Tongkat Fajar, dan Tongkat Cahaya Pertama. Setiap serangan yang kena memberi sedikit XP Iman, dan senjata ini melukai mayat hidup (kerangka, bayangan, dan Hampa) lebih parah.", "อาวุธศรัทธา ที่ต้องใช้ศรัทธาร่วมกับโจมตีหรือเวทมนตร์: ดาบเหล็กรุ่งอรุณ หอกยามเฝ้า ดาบใหญ่เรืองรอง และค้อนศึกตีด้วยตะวัน รวมถึงคทาผู้ช่วยนักบวช คทารุ่งอรุณ และคทาแห่งแสงแรก ทุกครั้งที่โจมตีโดนจะได้ XP ศรัทธาเล็กน้อย และทำร้ายอันเดด (โครงกระดูก เงา และความว่างเปล่า) ได้แรงกว่า", "Saldırı veya Büyünün yanı sıra İnanç da isteyen İnanç silahları: Şafak çeliği kılıç, Nöbet mızrağı, Işıltılı büyük kılıç ve Güneşte dövülmüş savaş çekici; ayrıca Yardımcı rahip asası, Şafak asası ve İlk Işığın Asası. İsabet eden her vuruş biraz İnanç XP'si verir ve ölümsüzlere (iskeletler, gölgeler ve Boşluk) daha çok acıtır.", "Armas de Fe, que piden Fe además de Ataque o Magia: la Espada de acero del alba, la Lanza de vigilia, el Mandoble radiante y el Martillo de guerra forjado al sol, y el Bastón de acólito, el Bastón del Alba y el Bastón de la Primera Luz. Cada golpe que aciertas da un poco de XP de Fe, y hacen más daño a los no muertos (esqueletos, sombras y el Hueco).", "Armas de Fé, que pedem Fé além de Ataque ou Magia: a Espada de aço-da-aurora, a Lança da vigília, o Montante radiante e o Martelo de guerra forjado ao sol, e o Cajado de acólito, o Cajado da Aurora e o Cajado da Primeira Luz. Cada golpe que acerta dá um pouco de XP de Fé, e elas ferem mais os mortos-vivos (esqueletos, sombras e o Oco).", "Оружие Веры, которому нужна Вера вдобавок к Атаке или Магии: меч из стали зари, копьё бдения, сияющий двуручный меч и солнцекованый боевой молот, а также посох послушника, Посох Зари и Посох Первого Света. Каждое попадание даёт немного опыта Веры, а нежить (скелеты, тени и Пустота) они ранят сильнее.", "Зброя Віри, якій потрібна Віра на додачу до Атаки чи Магії: меч зі сталі світанку, спис чування, сяйливий дворучний меч і сонцекований бойовий молот, а також посох прислужника, Посох Світанку й Посох Першого Світла. Кожне влучання дає трохи досвіду Віри, а нежить (скелети, тіні й Порожнеча) вони ранять сильніше."],
  "More ways to train Faith: use bones on any altar to offer them for twice the XP of burying, or three times on the Dawnhold chapel altar.": ["信仰を鍛える方法が増えました：どの祭壇でも骨を使って捧げると埋葬の2倍、ドーンホールドの礼拝堂の祭壇なら3倍の経験値。", "신앙을 훈련할 방법이 늘었습니다: 아무 제단에나 뼈를 사용해 바치면 묻을 때의 두 배, 돈홀드 예배당 제단에선 세 배의 경험치.", "训练信仰的新方法：在任何祭坛上对其使用骨头进行供奉，经验是掩埋的两倍，在晨堡礼拜堂祭坛上是三倍。", "訓練信仰的新方法：在任何祭壇上對其使用骨頭進行供奉，經驗是掩埋的兩倍，在晨堡禮拜堂祭壇上是三倍。", "Thêm cách luyện Đức tin: dùng xương trên bất kỳ bàn thờ nào để dâng, được gấp đôi XP so với chôn, hoặc gấp ba trên bàn thờ nhà nguyện Dawnhold.", "Lebih banyak cara melatih Iman: gunakan tulang di altar mana pun untuk mempersembahkannya, XP dua kali lipat dari mengubur, atau tiga kali di altar kapel Dawnhold.", "วิธีฝึกศรัทธาเพิ่มเติม: ใช้กระดูกกับแท่นบูชาใดก็ได้เพื่อถวาย ได้ XP สองเท่าของการฝัง หรือสามเท่าที่แท่นบูชาโบสถ์ดอว์นโฮลด์", "İnancı eğitmenin yeni yolları: kemikleri herhangi bir sunakta kullanarak sun, gömmenin iki katı XP; Dawnhold şapelinin sunağında üç katı.", "Más formas de entrenar Fe: usa huesos en cualquier altar para ofrecerlos por el doble de XP que enterrarlos, o el triple en el altar de la capilla de Dawnhold.", "Mais jeitos de treinar Fé: use ossos em qualquer altar para oferecê-los pelo dobro do XP de enterrar, ou o triplo no altar da capela de Dawnhold.", "Больше способов качать Веру: используйте кости на любом алтаре, чтобы принести их в дар, — вдвое больше опыта, чем за погребение, а на алтаре часовни Даунхолда втрое.", "Більше способів розвивати Віру: використайте кістки на будь-якому вівтарі, щоб принести їх у дар, — удвічі більше досвіду, ніж за поховання, а на вівтарі каплиці Даунголда втричі."],
  "Capes, hats and amulets, and sharper guards": ["マント、帽子、アミュレット、そして凛々しい衛兵", "망토, 모자, 부적, 그리고 더 늠름한 경비병", "披风、帽子与护符，以及更精神的守卫", "披風、帽子與護符，以及更精神的守衛", "Áo choàng, mũ, bùa hộ mệnh và lính gác bảnh bao hơn", "Jubah, topi, jimat, dan penjaga yang lebih gagah", "ผ้าคลุม หมวก เครื่องราง และยามที่ดูดีขึ้น", "Pelerinler, şapkalar, muskalar ve daha şık muhafızlar", "Capas, sombreros y amuletos, y guardias más apuestos", "Capas, chapéus e amuletos, e guardas mais garbosos", "Плащи, шляпы, амулеты и бравые стражники", "Плащі, капелюхи, амулети й бравіші вартові"],
  "Threadneedle Tailors on Market Street, across from Heft & Haft: capes in ten solid colours and seven patterns (stripes, halves, a chevron, quarters, a gold border, stars and a pilgrim's cross), wizard hats in six colours, feathered caps and wide-brimmed traveller's hats.": ["重柄堂の向かい、Market Street にスレッドニードル仕立て屋：単色10色と柄7種（ストライプ、ハーフ、山形、四分割、金の縁取り、星、巡礼者の十字）のマント、6色の魔法使いの帽子、羽根付き帽子、つば広の旅人帽。", "중자루상 맞은편 Market Street의 스레드니들 양복점: 단색 열 가지와 무늬 일곱 가지(줄무늬, 반반, 갈매기, 사분할, 금 테두리, 별, 순례자의 십자)의 망토, 여섯 색의 마법사 모자, 깃털 모자, 챙 넓은 여행자 모자.", "Market Street 上「重柄」对面的穿针裁缝铺：十种纯色和七种图案（条纹、对半、人字纹、四分、金边、星星和朝圣者十字）的披风，六种颜色的巫师帽，羽毛帽和宽檐旅行帽。", "Market Street 上「重柄」對面的穿針裁縫鋪：十種純色和七種圖案（條紋、對半、人字紋、四分、金邊、星星和朝聖者十字）的披風，六種顏色的巫師帽，羽毛帽和寬簷旅行帽。", "Tiệm may Threadneedle trên Market Street, đối diện Heft & Haft: áo choàng mười màu trơn và bảy họa tiết (sọc, nửa nọ nửa kia, chữ V, bốn ô, viền vàng, ngôi sao và thánh giá hành hương), mũ phù thủy sáu màu, mũ gắn lông và mũ lữ khách vành rộng.", "Penjahit Threadneedle di Market Street, di seberang Heft & Haft: jubah dalam sepuluh warna polos dan tujuh pola (garis, belah dua, chevron, perempat, pinggiran emas, bintang, dan salib peziarah), topi penyihir dalam enam warna, topi berbulu, dan topi pengelana bertepi lebar.", "ร้านตัดเสื้อเธรดนีดเดิลบน Market Street ตรงข้ามเฮฟต์แอนด์ฮาฟต์: ผ้าคลุมสีพื้นสิบสีและลายเจ็ดแบบ (ลายทาง สองซีก บั้ง สี่ส่วน ขอบทอง ดาว และกางเขนผู้แสวงบุญ) หมวกพ่อมดหกสี หมวกประดับขน และหมวกนักเดินทางปีกกว้าง", "Market Street'te Heft & Haft'ın karşısında Threadneedle Terzileri: on düz renk ve yedi desende (çizgili, ikiye bölünmüş, şerit, dörde bölünmüş, altın kenarlı, yıldızlı ve hacı haçlı) pelerinler, altı renkte büyücü şapkaları, tüylü kasketler ve geniş kenarlı yolcu şapkaları.", "La Sastrería Hilo y Aguja en Market Street, frente a Heft & Haft: capas en diez colores lisos y siete diseños (rayas, mitades, un cheurón, cuarteles, borde dorado, estrellas y una cruz de peregrino), sombreros de mago en seis colores, gorras con pluma y sombreros de viajero de ala ancha.", "A Alfaiataria Linha e Agulha na Market Street, em frente à Heft & Haft: capas em dez cores lisas e sete padrões (listras, metades, uma divisa, quartos, borda dourada, estrelas e uma cruz de peregrino), chapéus de mago em seis cores, bonés com pena e chapéus de viajante de aba larga.", "Портные «Нить и игла» на Market Street, напротив «Веса и древка»: плащи десяти однотонных цветов и семи узоров (полосы, половины, шеврон, четверти, золотая кайма, звёзды и крест паломника), шляпы волшебника шести цветов, шапочки с пером и широкополые шляпы путника.", "Кравці «Нитка й голка» на Market Street, навпроти «Ваги й держака»: плащі десяти однотонних кольорів і семи візерунків (смуги, половини, шеврон, чверті, золота облямівка, зірки й хрест прочанина), капелюхи чарівника шести кольорів, шапочки з пером і крислаті капелюхи мандрівника."],
  "Amulets and pendants show on your Friend now (and on other players), hanging round the neck.": ["アミュレットとペンダントが首から下がった状態でフレンドに（ほかのプレイヤーにも）表示されるようになりました。", "부적과 펜던트가 이제 목에 걸린 채로 프렌드에게(다른 플레이어에게도) 보입니다.", "护符和吊坠现在会挂在伙伴（以及其他玩家）的脖子上显示出来。", "護符和吊墜現在會掛在夥伴（以及其他玩家）的脖子上顯示出來。", "Bùa hộ mệnh và mặt dây chuyền giờ hiện trên Bạn của bạn (và người chơi khác), đeo quanh cổ.", "Jimat dan liontin kini tampak pada Sahabatmu (dan pemain lain), tergantung di leher.", "เครื่องรางและจี้ตอนนี้แสดงบนเพื่อนของคุณ (และผู้เล่นอื่น) ห้อยอยู่ที่คอ", "Muskalar ve kolyeler artık Dostunda (ve diğer oyuncularda) boynunda asılı görünüyor.", "Los amuletos y colgantes se ven ahora en tu Amigo (y en otros jugadores), colgados del cuello.", "Amuletos e pingentes agora aparecem no seu Amigo (e em outros jogadores), pendurados no pescoço.", "Амулеты и подвески теперь видны на вашем Друге (и на других игроках) — висят на шее.", "Амулети й підвіски тепер видно на вашому Другові (і на інших гравцях) — висять на шиї."],
  "Seen from behind, your weapon or tool is held beside your cape instead of cutting across it.": ["後ろから見ると、武器や道具がマントを横切らず、マントの横に持たれるように。", "뒤에서 보면 무기나 도구가 망토를 가로지르지 않고 망토 옆에 들려 있습니다.", "从背后看，武器或工具握在披风旁边，而不是横穿过披风。", "從背後看，武器或工具握在披風旁邊，而不是橫穿過披風。", "Nhìn từ phía sau, vũ khí hay dụng cụ được cầm bên cạnh áo choàng thay vì cắt ngang qua nó.", "Dilihat dari belakang, senjata atau alatmu dipegang di samping jubah, tidak memotongnya.", "มองจากด้านหลัง อาวุธหรือเครื่องมือจะถืออยู่ข้างผ้าคลุมแทนที่จะพาดผ่าน", "Arkadan bakıldığında silahın ya da aletin pelerininin üstünden geçmek yerine yanında tutuluyor.", "Visto desde detrás, tu arma o herramienta va junto a la capa en vez de atravesarla.", "Vista de trás, sua arma ou ferramenta fica ao lado da capa em vez de cortá-la.", "Если смотреть сзади, оружие или инструмент держится рядом с плащом, а не поперёк него.", "Якщо дивитися ззаду, зброя чи інструмент тримається поруч із плащем, а не впоперек нього."],
  "The castle guards wear helms and red capes and carry battleaxes; Captain Rook carries a greatsword.": ["城の衛兵は兜と赤いマントを身につけ、戦斧を持っています。ルーク隊長は大剣を持っています。", "성 경비병은 투구와 빨간 망토를 쓰고 전투도끼를 듭니다. 루크 대장은 대검을 듭니다.", "城堡守卫戴着头盔、披着红披风、手持战斧；鲁克队长手持巨剑。", "城堡守衛戴著頭盔、披著紅披風、手持戰斧；魯克隊長手持巨劍。", "Lính gác lâu đài đội mũ giáp, khoác áo choàng đỏ và mang rìu chiến; Đội trưởng Rook mang đại kiếm.", "Penjaga kastel memakai helm dan jubah merah serta membawa kapak perang; Kapten Rook membawa pedang besar.", "ยามปราสาทสวมหมวกเกราะและผ้าคลุมแดง ถือขวานศึก กัปตันรุกถือดาบใหญ่", "Kale muhafızları miğfer ve kırmızı pelerin giyip savaş baltası taşıyor; Yüzbaşı Rook büyük bir kılıç taşıyor.", "Los guardias del castillo llevan yelmo y capa roja y hachas de batalla; el capitán Rook lleva un mandoble.", "Os guardas do castelo usam elmos e capas vermelhas e carregam machados de batalha; o Capitão Rook carrega um montante.", "Стражники замка носят шлемы и красные плащи и вооружены боевыми топорами; капитан Рук — двуручным мечом.", "Вартові замку носять шоломи й червоні плащі та озброєні бойовими сокирами; капітан Рук — дворучним мечем."],
  "Snowy peaks no longer vanish when you turn the camera (the land is drawn back to front at every angle), and the distance haze follows the land, so nearby mountains are never hazed.": ["カメラを回しても雪山が消えなくなり（どの角度でも奥から手前へ描画）、遠景のもやも地形に沿うので、近くの山がかすむことはありません。", "카메라를 돌려도 눈 덮인 봉우리가 사라지지 않고(모든 각도에서 뒤에서 앞으로 그립니다), 원경 아지랑이가 지형을 따라가 가까운 산은 흐려지지 않습니다.", "转动镜头时雪峰不再消失（每个角度都从后往前绘制地形），远景雾霭也贴合地形，近处的山不会被雾化。", "轉動鏡頭時雪峰不再消失（每個角度都從後往前繪製地形），遠景霧靄也貼合地形，近處的山不會被霧化。", "Đỉnh núi tuyết không còn biến mất khi xoay máy quay (địa hình được vẽ từ sau ra trước ở mọi góc), và sương xa bám theo địa hình, nên núi gần không bao giờ bị mờ.", "Puncak bersalju tak lagi hilang saat kamera diputar (daratan digambar dari belakang ke depan di setiap sudut), dan kabut jarak mengikuti daratan, jadi gunung dekat tak pernah berkabut.", "ยอดเขาหิมะไม่หายไปอีกเมื่อหมุนกล้อง (วาดพื้นที่จากหลังมาหน้าทุกมุม) และหมอกระยะไกลตามพื้นที่ ภูเขาใกล้ๆ จึงไม่ถูกหมอกบัง", "Kamerayı çevirdiğinde karlı zirveler artık kaybolmuyor (arazi her açıda arkadan öne çiziliyor) ve uzaklık pusu araziyi izliyor, böylece yakındaki dağlar asla puslanmıyor.", "Las cumbres nevadas ya no desaparecen al girar la cámara (el terreno se dibuja de atrás adelante en cualquier ángulo), y la bruma de la distancia sigue al terreno, así que las montañas cercanas nunca quedan difuminadas.", "Os picos nevados não somem mais ao girar a câmera (o terreno é desenhado de trás para a frente em qualquer ângulo), e a névoa de distância segue o terreno, então as montanhas próximas nunca ficam enevoadas.", "Снежные вершины больше не исчезают при повороте камеры (земля рисуется от дальнего к ближнему под любым углом), а дымка расстояния следует за рельефом, так что близкие горы не затуманиваются.", "Засніжені вершини більше не зникають під час повороту камери (земля малюється від дальнього до ближнього під будь-яким кутом), а серпанок відстані йде за рельєфом, тож близькі гори не затуманюються."],
  "New lighting: real shadows, sunlight and lamplight": ["新しいライティング：本物の影、日光、ランプの明かり", "새 조명: 진짜 그림자, 햇빛, 등불", "全新光照：真实阴影、阳光与灯光", "全新光照：真實陰影、陽光與燈光", "Ánh sáng mới: bóng đổ thật, nắng và ánh đèn", "Pencahayaan baru: bayangan nyata, sinar matahari, dan cahaya lampu", "แสงใหม่: เงาจริง แสงแดด และแสงตะเกียง", "Yeni aydınlatma: gerçek gölgeler, güneş ışığı ve lamba ışığı", "Nueva iluminación: sombras reales, luz del sol y de los faroles", "Nova iluminação: sombras reais, luz do sol e de lampiões", "Новое освещение: настоящие тени, солнечный свет и свет фонарей", "Нове освітлення: справжні тіні, сонячне світло й світло ліхтарів"],
  "The sun moves across the sky: it rises in the east, crosses the south and sets in the west. Buildings, walls, trees, rocks, characters and mounts cast shadows that follow it, long and golden at dawn and dusk, short at noon, and faint in the moonlight.": ["太陽が空を移動します：東から昇り、南を渡り、西に沈む。建物、壁、木、岩、キャラクター、騎乗動物が太陽に合わせて影を落とし、夜明けと夕暮れには長く金色に、正午には短く、月明かりではかすかに。", "해가 하늘을 가로지릅니다: 동쪽에서 떠서 남쪽을 지나 서쪽으로 집니다. 건물, 벽, 나무, 바위, 캐릭터, 탈것이 해를 따라 그림자를 드리우며, 새벽과 해 질 녘엔 길고 금빛으로, 정오엔 짧게, 달빛 아래선 희미하게.", "太阳划过天空：东升、经南、西落。建筑、墙壁、树木、岩石、角色和坐骑都会投下随太阳移动的影子，黎明和黄昏时又长又金，正午时很短，月光下则很淡。", "太陽劃過天空：東升、經南、西落。建築、牆壁、樹木、岩石、角色和坐騎都會投下隨太陽移動的影子，黎明和黃昏時又長又金，正午時很短，月光下則很淡。", "Mặt trời di chuyển trên bầu trời: mọc ở đông, qua phía nam và lặn ở tây. Nhà cửa, tường, cây, đá, nhân vật và thú cưỡi đổ bóng theo nó, dài và vàng óng lúc bình minh và hoàng hôn, ngắn lúc giữa trưa, và mờ dưới ánh trăng.", "Matahari bergerak melintasi langit: terbit di timur, melintasi selatan, dan terbenam di barat. Bangunan, dinding, pohon, batu, karakter, dan tunggangan membentuk bayangan yang mengikutinya, panjang dan keemasan saat fajar dan senja, pendek saat siang, dan samar di bawah cahaya bulan.", "ดวงอาทิตย์เคลื่อนผ่านท้องฟ้า: ขึ้นทางตะวันออก ผ่านทิศใต้ และตกทางตะวันตก อาคาร กำแพง ต้นไม้ หิน ตัวละคร และพาหนะทอดเงาตาม ยาวและสีทองยามรุ่งและยามพลบ สั้นตอนเที่ยง และจางใต้แสงจันทร์", "Güneş gökyüzünde ilerliyor: doğudan doğar, güneyden geçer ve batıdan batar. Binalar, duvarlar, ağaçlar, kayalar, karakterler ve binekler onu izleyen gölgeler düşürür; şafakta ve alacakaranlıkta uzun ve altın renkli, öğlen kısa, ay ışığında soluk.", "El sol recorre el cielo: sale por el este, cruza el sur y se pone por el oeste. Edificios, muros, árboles, rocas, personajes y monturas proyectan sombras que lo siguen, largas y doradas al alba y al atardecer, cortas a mediodía y tenues a la luz de la luna.", "O sol atravessa o céu: nasce no leste, cruza o sul e se põe no oeste. Prédios, muros, árvores, pedras, personagens e montarias projetam sombras que o acompanham, longas e douradas no amanhecer e no entardecer, curtas ao meio-dia e fracas ao luar.", "Солнце движется по небу: встаёт на востоке, проходит юг и садится на западе. Здания, стены, деревья, камни, персонажи и скакуны отбрасывают тени, которые следуют за ним: длинные и золотые на рассвете и закате, короткие в полдень и бледные при луне.", "Сонце рухається небом: сходить на сході, минає південь і сідає на заході. Будівлі, стіни, дерева, камені, персонажі й скакуни відкидають тіні, що йдуть за ним: довгі й золоті на світанку та смерканні, короткі опівдні й бліді при місяці."],
  "Lamps, torches, fires, forges and spells light the ground and everything standing near them instead of glowing over it, and walls, rocks and trees block their light.": ["ランプ、松明、火、鍛冶炉、呪文は、上に光を重ねるのではなく地面と近くに立つすべてを照らし、壁や岩、木はその光を遮ります。", "등불, 횃불, 불, 대장간, 주문이 위에서 빛나는 대신 바닥과 가까이 서 있는 모든 것을 비추고, 벽과 바위, 나무가 그 빛을 막습니다.", "灯、火把、火堆、锻炉和法术会照亮地面和附近的一切，而不是浮在上面发光，墙壁、岩石和树木会挡住它们的光。", "燈、火把、火堆、鍛爐和法術會照亮地面和附近的一切，而不是浮在上面發光，牆壁、岩石和樹木會擋住它們的光。", "Đèn, đuốc, lửa, lò rèn và phép thuật soi sáng mặt đất và mọi thứ đứng gần thay vì phát sáng phía trên, và tường, đá, cây chặn ánh sáng của chúng.", "Lampu, obor, api, tempa, dan mantra menerangi tanah dan semua yang berdiri di dekatnya alih-alih bersinar di atasnya, dan dinding, batu, serta pohon menghalangi cahayanya.", "ตะเกียง คบเพลิง ไฟ เตาตีเหล็ก และคาถาส่องสว่างพื้นและทุกสิ่งที่อยู่ใกล้แทนที่จะเรืองแสงทับ และกำแพง หิน ต้นไม้บังแสงได้", "Lambalar, meşaleler, ateşler, ocaklar ve büyüler üstünde parlamak yerine zemini ve yakınlarındaki her şeyi aydınlatır; duvarlar, kayalar ve ağaçlar ışıklarını keser.", "Lámparas, antorchas, fuegos, forjas y hechizos iluminan el suelo y todo lo que tienen cerca en lugar de brillar por encima, y muros, rocas y árboles bloquean su luz.", "Lampiões, tochas, fogueiras, forjas e feitiços iluminam o chão e tudo que está perto em vez de brilhar por cima, e muros, pedras e árvores bloqueiam a luz.", "Фонари, факелы, костры, горны и заклинания освещают землю и всё, что стоит рядом, а не светятся поверх, и стены, камни и деревья загораживают их свет.", "Ліхтарі, смолоскипи, вогнища, горни й заклинання освітлюють землю й усе, що стоїть поруч, а не світяться поверх, і стіни, камені та дерева затуляють їхнє світло."],
  "Light bounces: a fire's glow spills softly round corners in the colour of the ground, lava lights up everything around it, and dungeons are truly dark away from the flames.": ["光が反射します：火の明かりは地面の色を帯びて角の向こうへやわらかくこぼれ、溶岩は周囲すべてを照らし、ダンジョンは炎から離れると本当に暗くなります。", "빛이 반사됩니다: 불빛은 바닥 색을 띠고 모퉁이 너머로 부드럽게 번지고, 용암은 주변을 모두 밝히며, 던전은 불꽃에서 떨어지면 정말로 어둡습니다.", "光会反射：火光带着地面的颜色柔和地漫过拐角，岩浆照亮周围的一切，远离火焰的地下城真正漆黑。", "光會反射：火光帶著地面的顏色柔和地漫過轉角，岩漿照亮周圍的一切，遠離火焰的地下城真正漆黑。", "Ánh sáng phản chiếu: ánh lửa lan dịu quanh góc tường theo màu mặt đất, dung nham soi sáng mọi thứ xung quanh, và hầm ngục thật sự tối khi xa ngọn lửa.", "Cahaya memantul: cahaya api meluber lembut di tikungan dengan warna tanah, lava menerangi segala di sekitarnya, dan ruang bawah tanah benar-benar gelap jauh dari nyala api.", "แสงสะท้อน: แสงไฟไหลอ้อมมุมอย่างนุ่มนวลตามสีพื้น ลาวาส่องสว่างทุกอย่างรอบตัว และดันเจี้ยนมืดสนิทเมื่ออยู่ห่างเปลวไฟ", "Işık yansıyor: ateşin parıltısı zeminin renginde köşelerden yumuşakça taşar, lav çevresindeki her şeyi aydınlatır ve zindanlar alevlerden uzakta gerçekten karanlıktır.", "La luz rebota: el resplandor de un fuego se derrama suavemente por las esquinas con el color del suelo, la lava ilumina todo a su alrededor y las mazmorras son oscuras de verdad lejos de las llamas.", "A luz rebate: o brilho de uma fogueira se espalha suave pelas quinas na cor do chão, a lava ilumina tudo ao redor e as masmorras são escuras de verdade longe das chamas.", "Свет отражается: отблеск костра мягко растекается за углы в цвет земли, лава освещает всё вокруг, а подземелья по-настоящему темны вдали от пламени.", "Світло відбивається: відблиск вогнища м'яко розтікається за рогами в колір землі, лава освітлює все довкола, а підземелля по-справжньому темні подалі від полум'я."],
  "Softer ambient light: corners, alleys, forest floors and the spaces under roofs are darker, and the sky's colour changes through the day. At night the haze and fog turn a dim blue.": ["よりやわらかな環境光：角、路地、森の地面、屋根の下は暗くなり、空の色は一日を通して変わります。夜にはもやと霧がほの暗い青に。", "더 부드러운 주변광: 모퉁이, 골목, 숲 바닥, 지붕 아래는 더 어둡고, 하늘 색은 하루 동안 바뀝니다. 밤엔 아지랑이와 안개가 어스름한 파랑이 됩니다.", "更柔和的环境光：角落、小巷、林地和屋檐下更暗，天空颜色随一天变化。夜晚的雾霭会变成暗蓝色。", "更柔和的環境光：角落、小巷、林地和屋簷下更暗，天空顏色隨一天變化。夜晚的霧靄會變成暗藍色。", "Ánh sáng môi trường dịu hơn: góc khuất, ngõ hẻm, nền rừng và khoảng dưới mái tối hơn, và màu trời thay đổi suốt ngày. Ban đêm, sương mù chuyển sang xanh lam mờ.", "Cahaya sekitar lebih lembut: sudut, gang, lantai hutan, dan ruang di bawah atap lebih gelap, dan warna langit berubah sepanjang hari. Di malam hari kabut menjadi biru redup.", "แสงโดยรอบนุ่มขึ้น: มุม ตรอก พื้นป่า และใต้หลังคามืดขึ้น และสีท้องฟ้าเปลี่ยนตลอดวัน กลางคืนหมอกกลายเป็นสีน้ำเงินสลัว", "Daha yumuşak ortam ışığı: köşeler, ara sokaklar, orman tabanları ve çatı altları daha karanlık ve gökyüzünün rengi gün boyu değişiyor. Gece pus ve sis loş bir maviye dönüyor.", "Luz ambiental más suave: esquinas, callejones, suelos de bosque y los huecos bajo los tejados son más oscuros, y el color del cielo cambia a lo largo del día. De noche la bruma y la niebla se vuelven de un azul tenue.", "Luz ambiente mais suave: cantos, becos, chão de floresta e os espaços sob os telhados ficam mais escuros, e a cor do céu muda ao longo do dia. À noite a névoa e a neblina ficam de um azul fraco.", "Более мягкий фоновый свет: углы, переулки, лесная подстилка и пространство под крышами темнее, а цвет неба меняется в течение дня. Ночью дымка и туман становятся тускло-синими.", "М'якше фонове світло: кути, провулки, лісова підстилка й простір під дахами темніші, а колір неба змінюється впродовж дня. Уночі серпанок і туман стають тьмяно-синіми."],
  "On Low graphics a clear day is drawn as before, and nights stay lit, without the shadows.": ["低画質では晴れた日は以前どおりに描かれ、夜も明るいまま、影はありません。", "그래픽 낮음에선 맑은 날은 예전처럼 그려지고, 밤도 밝게 유지되며 그림자는 없습니다.", "低画质下，晴天按以前的方式绘制，夜晚保持明亮，没有阴影。", "低畫質下，晴天按以前的方式繪製，夜晚保持明亮，沒有陰影。", "Ở đồ họa Thấp, ngày quang đãng được vẽ như trước, và đêm vẫn sáng, không có bóng đổ.", "Pada grafis Rendah, hari cerah digambar seperti sebelumnya, dan malam tetap terang, tanpa bayangan.", "ในกราฟิกต่ำ วันฟ้าใสวาดเหมือนเดิม และกลางคืนยังสว่าง ไม่มีเงา", "Düşük grafikte açık bir gün eskisi gibi çiziliyor ve geceler gölgesiz, aydınlık kalıyor.", "En gráficos Bajos un día despejado se dibuja como antes, y las noches siguen iluminadas, sin sombras.", "Nos gráficos Baixos um dia claro é desenhado como antes, e as noites continuam iluminadas, sem sombras.", "На низкой графике ясный день рисуется как раньше, а ночи остаются светлыми, без теней.", "На низькій графіці ясний день малюється як раніше, а ночі лишаються світлими, без тіней."],
  "Two-handed weapons, new creatures and sharper skill icons": ["両手武器、新しい生き物、くっきりしたスキルアイコン", "양손 무기, 새 생물, 더 선명한 스킬 아이콘", "双手武器、新生物与更清晰的技能图标", "雙手武器、新生物與更清晰的技能圖示", "Vũ khí hai tay, sinh vật mới và biểu tượng kỹ năng sắc nét hơn", "Senjata dua tangan, makhluk baru, dan ikon keahlian yang lebih tajam", "อาวุธสองมือ สิ่งมีชีวิตใหม่ และไอคอนทักษะที่คมชัดขึ้น", "İki elli silahlar, yeni yaratıklar ve daha net beceri simgeleri", "Armas a dos manos, criaturas nuevas e iconos de habilidad más nítidos", "Armas de duas mãos, criaturas novas e ícones de habilidade mais nítidos", "Двуручное оружие, новые существа и чёткие значки навыков", "Дворучна зброя, нові істоти й чіткіші значки навичок"],
  "Two-handed greatswords, battleaxes and war hammers in every metal: a tick slower than a sword and much harder hitting, with no room for a shield. Smith them at an anvil (3 bars), or buy them at Heft & Haft, the new shop at the south end of Market Street.": ["全金属で両手持ちの大剣、戦斧、ウォーハンマー：剣より1ティック遅いぶん威力ははるかに高く、盾は持てません。金床で鍛える（延べ棒3本）か、Market Street の南端にできた新しい店、重柄堂で買えます。", "모든 금속의 양손 대검, 전투도끼, 전쟁망치: 검보다 한 틱 느리지만 훨씬 세고, 방패를 들 수 없습니다. 모루에서 만들거나(주괴 3개) Market Street 남쪽 끝의 새 가게 중자루상에서 사세요.", "各种金属的双手巨剑、战斧和战锤：比剑慢一刻但威力大得多，无法持盾。可在铁砧上锻造（3 块锭），也可在 Market Street 南端的新店「重柄」购买。", "各種金屬的雙手巨劍、戰斧和戰錘：比劍慢一刻但威力大得多，無法持盾。可在鐵砧上鍛造（3 塊錠），也可在 Market Street 南端的新店「重柄」購買。", "Đại kiếm, rìu chiến và búa chiến hai tay bằng mọi kim loại: chậm hơn kiếm một nhịp nhưng đánh mạnh hơn nhiều, và không cầm được khiên. Rèn trên đe (3 thỏi), hoặc mua ở Heft & Haft, cửa hàng mới ở cuối phía nam Market Street.", "Pedang besar, kapak perang, dan palu perang dua tangan dari setiap logam: satu tik lebih lambat dari pedang dan jauh lebih keras, tanpa ruang untuk perisai. Tempa di landasan (3 batangan), atau beli di Heft & Haft, toko baru di ujung selatan Market Street.", "ดาบใหญ่ ขวานศึก และค้อนศึกสองมือทุกโลหะ: ช้ากว่าดาบหนึ่งจังหวะแต่แรงกว่ามาก และถือโล่ไม่ได้ ตีที่ทั่ง (3 แท่ง) หรือซื้อที่เฮฟต์แอนด์ฮาฟต์ ร้านใหม่ปลายใต้ของ Market Street", "Her metalden iki elli büyük kılıçlar, savaş baltaları ve savaş çekiçleri: kılıçtan bir tik yavaş, çok daha sert vurur ve kalkana yer bırakmaz. Örste dövebilir (3 külçe) ya da Market Street'in güney ucundaki yeni dükkân Heft & Haft'tan alabilirsin.", "Mandobles, hachas de batalla y martillos de guerra a dos manos en todos los metales: un tic más lentos que una espada y mucho más contundentes, sin hueco para escudo. Fórjalos en un yunque (3 lingotes) o cómpralos en Heft & Haft, la tienda nueva al sur de Market Street.", "Montantes, machados de batalha e martelos de guerra de duas mãos em todos os metais: um tique mais lentos que uma espada e muito mais fortes, sem espaço para escudo. Forje numa bigorna (3 barras) ou compre na Heft & Haft, a loja nova no extremo sul da Market Street.", "Двуручные мечи, боевые топоры и боевые молоты из всех металлов: на тик медленнее меча и бьют гораздо сильнее, без места для щита. Куйте их на наковальне (3 слитка) или покупайте в «Весе и древке», новой лавке в южном конце Market Street.", "Дворучні мечі, бойові сокири й бойові молоти з усіх металів: на тік повільніші за меч і б'ють набагато сильніше, без місця для щита. Куйте їх на ковадлі (3 злитки) або купуйте у «Вазі й держаку», новій крамниці в південному кінці Market Street."],
  "New creatures: forest spiders in Whisperwood, wild boars in the southern woods, sand scorpions in the Pale Dunes, highland goats on the Greyhorn slopes and stone golems in the Greyhorn mine.": ["新しい生き物：ささやきの森の森の蜘蛛、南の森のイノシシ、ペイル砂丘の砂サソリ、グレイホーンの斜面の高地のヤギ、そしてグレイホーン鉱山の石のゴーレム。", "새 생물: 속삭임숲의 숲 거미, 남쪽 숲의 멧돼지, 창백한 사구의 모래 전갈, 그레이혼 비탈의 고지 염소, 그레이혼 광산의 돌 골렘.", "新生物：低语林的森林蜘蛛、南方树林的野猪、苍白沙丘的沙蝎、灰角山坡的高地山羊，以及灰角矿的石魔像。", "新生物：低語林的森林蜘蛛、南方樹林的野豬、蒼白沙丘的沙蠍、灰角山坡的高地山羊，以及灰角礦的石魔像。", "Sinh vật mới: nhện rừng ở Whisperwood, lợn rừng ở rừng phía nam, bọ cạp cát ở Pale Dunes, dê cao nguyên trên sườn Greyhorn và golem đá trong mỏ Greyhorn.", "Makhluk baru: laba-laba hutan di Whisperwood, babi hutan di hutan selatan, kalajengking pasir di Pale Dunes, kambing dataran tinggi di lereng Greyhorn, dan golem batu di tambang Greyhorn.", "สิ่งมีชีวิตใหม่: แมงมุมป่าในป่ากระซิบ หมูป่าในป่าทางใต้ แมงป่องทรายในเนินทรายซีด แพะที่ราบสูงบนลาดเกรย์ฮอร์น และโกเลมหินในเหมืองเกรย์ฮอร์น", "Yeni yaratıklar: Whisperwood'da orman örümcekleri, güney ormanlarında yaban domuzları, Solgun Kumullar'da kum akrepleri, Greyhorn yamaçlarında yayla keçileri ve Greyhorn madeninde taş golemler.", "Criaturas nuevas: arañas del bosque en Whisperwood, jabalíes en los bosques del sur, escorpiones de arena en las Dunas Pálidas, cabras monteses en las laderas del Greyhorn y gólems de piedra en la mina Greyhorn.", "Criaturas novas: aranhas da floresta em Whisperwood, javalis nas matas do sul, escorpiões da areia nas Dunas Pálidas, cabras das terras altas nas encostas do Greyhorn e golens de pedra na mina Greyhorn.", "Новые существа: лесные пауки в Шепчущем лесу, кабаны в южных лесах, песчаные скорпионы в Бледных дюнах, горные козлы на склонах Грейхорна и каменные големы в руднике Грейхорна.", "Нові істоти: лісові павуки в Шепітливому лісі, кабани в південних лісах, піщані скорпіони в Блідих дюнах, гірські козли на схилах Грейгорна й кам'яні големи в копальні Грейгорна."],
  "Each has something only it drops: a spider-fang dagger, a two-handed Tusker axe, a Horned helm, a Stinger sabre and a Golem maul. Grumblins now carry the odd Grumblin spear, and moss colossi a Mossy staff or a Mossblade.": ["それぞれ専用のドロップがあります：蜘蛛の牙の短剣、両手持ちの牙獣の斧、角付きの兜、毒針のサーベル、ゴーレムの大槌。グランブリンはまれにグランブリンの槍を、苔の巨像は苔むした杖か苔の刃を持つように。", "각자 그것만 떨어뜨리는 게 있습니다: 거미 송곳니 단검, 양손 엄니 도끼, 뿔 투구, 독침 세이버, 골렘 대형망치. 그럼블린은 가끔 그럼블린 창을, 이끼 거상은 이끼 낀 지팡이나 이끼칼날을 듭니다.", "每种都有专属掉落：蛛牙匕首、双手獠牙斧、角盔、毒刺军刀和魔像巨锤。嘟囔怪偶尔会带嘟囔怪长矛，苔藓巨像会带苔藓法杖或苔刃。", "每種都有專屬掉落：蛛牙匕首、雙手獠牙斧、角盔、毒刺軍刀和魔像巨錘。嘟囔怪偶爾會帶嘟囔怪長矛，苔蘚巨像會帶苔蘚法杖或苔刃。", "Mỗi loài có thứ chỉ nó rơi ra: dao găm nanh nhện, Rìu nanh lợn hai tay, Mũ giáp có sừng, Kiếm cong ngòi độc và Búa tạ Golem. Grumblin giờ thỉnh thoảng mang Giáo Grumblin, và khổng lồ rêu mang Gậy phủ rêu hoặc Lưỡi kiếm rêu.", "Masing-masing punya jarahan khusus: belati taring laba-laba, Kapak bertaring dua tangan, Helm bertanduk, Sabel penyengat, dan Palu godam golem. Grumblin kini sesekali membawa Tombak Grumblin, dan kolosus lumut membawa Tongkat berlumut atau Bilah lumut.", "แต่ละตัวมีของที่มีแค่มันดรอป: กริชเขี้ยวแมงมุม ขวานงาช้างสองมือ หมวกเกราะมีเขา ดาบโค้งเหล็กไน และค้อนยักษ์โกเลม กรัมบลินตอนนี้บางทีถือหอกกรัมบลิน และยักษ์มอสถือคทามีมอสหรือดาบมอส", "Her birinin yalnızca kendisinin düşürdüğü bir şey var: örümcek dişi hançer, iki elli Azı dişi balta, Boynuzlu miğfer, İğneli pala ve Golem tokmağı. Grumblinler artık ara sıra Grumblin mızrağı, yosun devleri Yosunlu asa ya da Yosun kılıç taşıyor.", "Cada una suelta algo exclusivo: una daga de colmillo de araña, un Hacha de colmillo a dos manos, un Yelmo con cuernos, un Sable aguijón y un Mazo de gólem. Los grumblins llevan ahora alguna Lanza de grumblin, y los colosos de musgo un Bastón musgoso o una Hoja de musgo.", "Cada uma solta algo exclusivo: uma adaga de presa de aranha, um Machado de presa de duas mãos, um Elmo com chifres, um Sabre ferrão e uma Marreta de golem. Os grumblins agora carregam às vezes uma Lança de grumblin, e os colossos de musgo um Cajado musgoso ou uma Lâmina de musgo.", "У каждого своя добыча: кинжал из паучьего клыка, двуручный топор клыкача, рогатый шлем, сабля-жало и кувалда голема. Грамблины теперь иногда носят копьё грамблина, а моховые колоссы — замшелый посох или моховой клинок.", "У кожного своя здобич: кинджал із павучого ікла, дворучна сокира ікла, рогатий шолом, шабля-жало й кувалда голема. Грамбліни тепер іноді носять спис грамбліна, а мохові колоси — замшілий посох або моховий клинок."],
  "The skill icons are redrawn, crisp and shaded like the items and tabs.": ["スキルアイコンを描き直し、アイテムやタブと同じくくっきりと陰影をつけました。", "스킬 아이콘을 새로 그려 아이템과 탭처럼 선명하고 음영이 들어갔습니다.", "技能图标已重绘，像物品和标签一样清晰且有阴影。", "技能圖示已重繪，像物品和分頁一樣清晰且有陰影。", "Biểu tượng kỹ năng được vẽ lại, sắc nét và có đổ bóng như vật phẩm và các thẻ.", "Ikon keahlian digambar ulang, tajam dan berbayang seperti barang dan tab.", "ไอคอนทักษะวาดใหม่ คมชัดและมีเงาเหมือนไอเท็มและแท็บ", "Beceri simgeleri yeniden çizildi; eşyalar ve sekmeler gibi net ve gölgeli.", "Los iconos de habilidad están redibujados, nítidos y sombreados como los objetos y las pestañas.", "Os ícones de habilidade foram redesenhados, nítidos e sombreados como os itens e as abas.", "Значки навыков перерисованы — чёткие и с тенями, как предметы и вкладки.", "Значки навичок перемальовано — чіткі й з тінями, як предмети та вкладки."],
  "Arrow shafts give 8 Fletching XP (up from 5).": ["矢柄の矢作り経験値が8に（5から増加）。", "화살대가 화살 제작 경험치 8을 줍니다(5에서 상향).", "箭杆现在给予 8 点制箭经验（原为 5）。", "箭桿現在給予 8 點制箭經驗（原為 5）。", "Thân tên cho 8 XP Làm tên (tăng từ 5).", "Batang panah memberi 8 XP Membuat panah (naik dari 5).", "ก้านลูกศรให้ XP ทำลูกธนู 8 (จาก 5)", "Ok gövdeleri 8 Okçuluk zanaatı XP'si veriyor (5'ten yükseldi).", "Las astas de flecha dan 8 de XP de Flechería (antes 5).", "As hastes de flecha dão 8 de XP de Arquearia (antes 5).", "Древки стрел дают 8 опыта Изготовления стрел (было 5).", "Древка стріл дають 8 досвіду Виготовлення стріл (було 5)."],
  "Highcairn, the Greyhorn Highlands, sheep and string": ["ハイケアン、グレイホーン高地、羊と弦", "하이케언, 그레이혼 고원, 양과 시위", "高冢、灰角高地、绵羊与弦", "高塚、灰角高地、綿羊與弦", "Highcairn, Cao nguyên Greyhorn, cừu và dây cung", "Highcairn, Dataran Tinggi Greyhorn, domba, dan tali", "ไฮแคร์น ที่ราบสูงเกรย์ฮอร์น แกะ และสายธนู", "Highcairn, Greyhorn Yaylaları, koyunlar ve kiriş", "Highcairn, las Tierras Altas de Greyhorn, ovejas y cuerda", "Highcairn, as Terras Altas de Greyhorn, ovelhas e corda", "Хайкэрн, Грейхорнское нагорье, овцы и тетива", "Гайкерн, Грейгорнське нагір'я, вівці й тятива"],
  "The Realm is bigger: east of the Pale Dunes and south of Frostpeak the island swells into the Greyhorn Highlands, with a ragged new coast. Snowy peaks, scree slopes and crags, all walkable, a mountain lake, and the Greyhorn mine (glimmer, rarite and moonsilver).": ["レルムが広くなりました：ペイル砂丘の東、フロストピークの南で島はグレイホーン高地へと広がり、ぎざぎざの新しい海岸ができました。雪山、ガレ場、岩山はすべて歩けて、山の湖とグレイホーン鉱山（グリマー、レアライト、ムーンシルバー）があります。", "렐름이 넓어졌습니다: 창백한 사구 동쪽, 프로스트피크 남쪽으로 섬이 그레이혼 고원으로 부풀며 들쭉날쭉한 새 해안이 생겼습니다. 걸어 다닐 수 있는 설산, 너덜 비탈, 바위산, 산상 호수, 그레이혼 광산(글리머, 레어라이트, 월은).", "王国变大了：在苍白沙丘以东、霜峰以南，岛屿隆起成灰角高地，有一段参差的新海岸。雪峰、碎石坡和峭壁都能走上去，还有一座高山湖和灰角矿（微光、稀晶和月银）。", "王國變大了：在蒼白沙丘以東、霜峰以南，島嶼隆起成灰角高地，有一段參差的新海岸。雪峰、碎石坡和峭壁都能走上去，還有一座高山湖和灰角礦（微光、稀晶和月銀）。", "Vương quốc rộng hơn: phía đông Pale Dunes và nam Frostpeak, hòn đảo phình ra thành Cao nguyên Greyhorn với bờ biển mới lởm chởm. Đỉnh tuyết, sườn đá vụn và vách núi, tất cả đều đi được, một hồ trên núi và mỏ Greyhorn (ánh kim, rarit và bạc trăng).", "Realm makin luas: di timur Pale Dunes dan selatan Frostpeak pulau ini membengkak menjadi Dataran Tinggi Greyhorn, dengan pantai baru yang bergerigi. Puncak bersalju, lereng kerikil, dan tebing, semua bisa dijelajahi, danau gunung, dan tambang Greyhorn (kemilau, rarit, dan perak bulan).", "อาณาจักรใหญ่ขึ้น: ทางตะวันออกของเนินทรายซีดและทางใต้ของฟรอสต์พีก เกาะขยายเป็นที่ราบสูงเกรย์ฮอร์น พร้อมชายฝั่งใหม่ขรุขระ ยอดเขาหิมะ ลาดหินกรวด และหน้าผา เดินได้ทั้งหมด ทะเลสาบบนภูเขา และเหมืองเกรย์ฮอร์น (ประกายแสง แรไรต์ และเงินจันทร์)", "Diyar büyüdü: Solgun Kumullar'ın doğusunda ve Frostpeak'in güneyinde ada, girintili çıkıntılı yeni bir kıyıyla Greyhorn Yaylaları'na doğru genişliyor. Karlı zirveler, taşlı yamaçlar ve kayalıklar (hepsi yürünebilir), bir dağ gölü ve Greyhorn madeni (parıltı, rarit ve ay gümüşü).", "El Reino es más grande: al este de las Dunas Pálidas y al sur de Frostpeak la isla se ensancha en las Tierras Altas de Greyhorn, con una costa nueva y escarpada. Cumbres nevadas, pedregales y riscos, todo transitable, un lago de montaña y la mina Greyhorn (destello, rarita y plata lunar).", "O Reino está maior: a leste das Dunas Pálidas e ao sul de Frostpeak a ilha se expande nas Terras Altas de Greyhorn, com uma costa nova e recortada. Picos nevados, encostas de cascalho e penhascos, tudo caminhável, um lago de montanha e a mina Greyhorn (lampejo, rarita e prata lunar).", "Королевство выросло: к востоку от Бледных дюн и к югу от Фростпика остров вздымается Грейхорнским нагорьем с новым изрезанным берегом. Снежные вершины, осыпи и скалы — по всем можно ходить, — горное озеро и рудник Грейхорна (мерцалит, рарит и лунное серебро).", "Королівство виросло: на схід від Блідих дюн і на південь від Фростпіку острів здіймається Грейгорнським нагір'ям із новим порізаним берегом. Засніжені вершини, осипи й скелі — усіма можна ходити, — гірське озеро й копальня Грейгорна (мерехтит, рарит і місячне срібло)."],
  "Highcairn, a stone town on a plateau in the middle: a bank, the Highcairn Stores, the Stone Kettle inn, the Highcairn Forge, a mountain shrine and a Rare Market trader. Roads climb to it from the Frostpeak camp and the Oasis.": ["中央の台地にある石の町、ハイケアン：銀行、ハイケアン商店、Stone Kettle の宿、ハイケアン鍛冶場、山の祠、そしてレアマーケットの商人。フロストピークの野営地とオアシスから道が登っています。", "한가운데 고원 위의 돌 마을 하이케언: 은행, 하이케언 상점, Stone Kettle 여관, 하이케언 대장간, 산속 사당, 레어 마켓 상인. 프로스트피크 야영지와 오아시스에서 길이 올라갑니다.", "高冢，位于中央高原上的石头小镇：银行、高冢商店、Stone Kettle 旅店、高冢铁匠铺、一座山间神龛和一名稀有市场商人。道路从霜峰营地和绿洲爬升而至。", "高塚，位於中央高原上的石頭小鎮：銀行、高塚商店、Stone Kettle 旅店、高塚鐵匠鋪、一座山間神龕和一名稀有市場商人。道路從霜峰營地和綠洲爬升而至。", "Highcairn, thị trấn đá trên cao nguyên ở giữa: ngân hàng, Cửa hàng Highcairn, quán trọ Stone Kettle, Lò rèn Highcairn, một miếu thờ trên núi và một thương nhân Chợ hiếm. Đường dốc lên đó từ trại Frostpeak và Ốc đảo.", "Highcairn, kota batu di dataran tinggi di tengah: bank, Toko Highcairn, penginapan Stone Kettle, Tempa Highcairn, kuil gunung, dan pedagang Pasar Langka. Jalan mendaki ke sana dari perkemahan Frostpeak dan Oasis.", "ไฮแคร์น เมืองหินบนที่ราบสูงตรงกลาง: ธนาคาร ร้านค้าไฮแคร์น โรงเตี๊ยม Stone Kettle โรงตีเหล็กไฮแคร์น ศาลเจ้าบนภูเขา และพ่อค้าตลาดหายาก มีถนนไต่ขึ้นมาจากค่ายฟรอสต์พีกและโอเอซิส", "Ortadaki bir platodaki taş kasaba Highcairn: bir banka, Highcairn Dükkânları, Stone Kettle hanı, Highcairn Demirhanesi, bir dağ tapınağı ve bir Nadir Pazar tüccarı. Yollar Frostpeak kampından ve Vaha'dan ona tırmanıyor.", "Highcairn, un pueblo de piedra en una meseta en el centro: un banco, los Almacenes de Highcairn, la posada Stone Kettle, la Forja de Highcairn, un santuario de montaña y un comerciante del Mercado raro. Los caminos suben hasta allí desde el campamento de Frostpeak y el Oasis.", "Highcairn, uma cidade de pedra num planalto no meio: um banco, os Armazéns de Highcairn, a estalagem Stone Kettle, a Forja de Highcairn, um santuário de montanha e um comerciante do Mercado Raro. Estradas sobem até lá do acampamento de Frostpeak e do Oásis.", "Хайкэрн — каменный город на плато посередине: банк, Лавки Хайкэрна, трактир Stone Kettle, Кузница Хайкэрна, горное святилище и торговец Редкого рынка. Дороги поднимаются к нему от лагеря Фростпика и от Оазиса.", "Гайкерн — кам'яне місто на плато посередині: банк, Крамниці Гайкерна, корчма Stone Kettle, Кузня Гайкерна, гірська святиня й торговець Рідкісного ринку. Дороги підіймаються до нього від табору Фростпіку та від Оазису."],
  "Sheep! A new pen between the cows and the chickens. Shear them with shears (any general store) for wool; a shorn sheep looks shorn until its fleece grows back.": ["羊！牛と鶏の間に新しい囲いができました。はさみ（どの雑貨屋でも）で毛を刈ると羊毛が手に入り、刈られた羊は毛が生え戻るまで刈られた姿のまま。", "양! 소와 닭 사이에 새 우리가 생겼습니다. 가위(아무 잡화점)로 털을 깎으면 양모가 나오고, 깎인 양은 털이 다시 자랄 때까지 깎인 모습입니다.", "绵羊！在牛和鸡之间有一个新羊圈。用剪刀（任何杂货店有售）剪毛获得羊毛；剪过毛的羊会保持光秃的样子，直到毛重新长出来。", "綿羊！在牛和雞之間有一個新羊圈。用剪刀（任何雜貨店有售）剪毛獲得羊毛；剪過毛的羊會保持光禿的樣子，直到毛重新長出來。", "Cừu! Một chuồng mới giữa đàn bò và đàn gà. Xén lông bằng kéo (cửa hàng tạp hóa nào cũng có) để lấy len; cừu bị xén trông trụi lông cho đến khi lông mọc lại.", "Domba! Kandang baru di antara sapi dan ayam. Cukur dengan gunting (toko kelontong mana pun) untuk wol; domba yang dicukur tampak gundul sampai bulunya tumbuh lagi.", "แกะ! คอกใหม่ระหว่างวัวกับไก่ ตัดขนด้วยกรรไกร (ร้านขายของทั่วไปทุกร้าน) เพื่อได้ขนแกะ แกะที่ถูกตัดขนจะดูโล้นจนกว่าขนจะงอกใหม่", "Koyunlar! İnekler ile tavukların arasında yeni bir ağıl. Yün için onları makasla kırk (her bakkalda); kırkılmış koyun yünü yeniden uzayana dek kırkılmış görünür.", "¡Ovejas! Un corral nuevo entre las vacas y las gallinas. Esquílalas con tijeras (en cualquier tienda general) para obtener lana; una oveja esquilada se ve esquilada hasta que le vuelve a crecer el vellón.", "Ovelhas! Um curral novo entre as vacas e as galinhas. Tosquie com tesouras (em qualquer armazém) para conseguir lã; uma ovelha tosquiada fica tosquiada até a lã crescer de novo.", "Овцы! Новый загон между коровами и курами. Стригите их ножницами (в любой лавке) ради шерсти; остриженная овца выглядит остриженной, пока руно не отрастёт.", "Вівці! Новий загін між коровами й курми. Стрижіть їх ножицями (у будь-якій крамниці) заради вовни; острижена вівця виглядає остриженою, доки руно не відросте."],
  "Spin wool into string at a spinning wheel (the farmhouse, or Tessa's tannery in Friendhollow): Crafting level 1.": ["糸車（農家か、フレンドホロウのテッサのなめし屋）で羊毛を紡いで弦に：工芸レベル1。", "물레(농가나 프렌드할로우의 테사 무두질 가게)에서 양모를 자아 시위로: 공예 레벨 1.", "在纺车上（农舍或友谷泰莎的制革坊）把羊毛纺成弦：手工 1 级。", "在紡車上（農舍或友谷泰莎的製革坊）把羊毛紡成弦：手工 1 級。", "Se len thành dây ở guồng quay tơ (nhà trang trại, hoặc xưởng thuộc da của Tessa ở Friendhollow): Thủ công cấp 1.", "Pintal wol menjadi tali di roda pintal (rumah pertanian, atau penyamakan Tessa di Friendhollow): Kerajinan level 1.", "ปั่นขนแกะเป็นสายที่เครื่องปั่นด้าย (บ้านไร่ หรือร้านฟอกหนังของเทสซาในเฟรนด์ฮอลโลว์): งานฝีมือเลเวล 1", "Yünü bir çıkrıkta (çiftlik evi ya da Friendhollow'daki Tessa'nın tabakhanesi) kirişe eğir: Zanaat seviye 1.", "Hila la lana en cuerda en una rueca (la granja, o la curtiduría de Tessa en Friendhollow): Artesanía nivel 1.", "Fie a lã em corda numa roca (a casa da fazenda ou o curtume da Tessa em Friendhollow): Artesanato nível 1.", "Прядите шерсть в тетиву на прялке (фермерский дом или дубильня Тессы во Френдхоллоу): Ремесло 1-го уровня.", "Прядіть вовну на тятиву на прядці (фермерський дім або чинбарня Тесси у Френдголлоу): Ремесло 1-го рівня."],
  "Bows need strings now: a knife on logs cuts an unstrung bow (or war bow), and a string finishes it. A string on a cut gem makes an amulet, and the Enchant spells turn moonstone and rosestone amulets into pendants.": ["弓には弦が必要になりました：丸太にナイフを使うと弦のない弓（またはウォーボウ）ができ、弦を張れば完成。研磨した宝石に弦を通すとアミュレットになり、エンチャントの呪文でムーンストーンとローズストーンのアミュレットがペンダントになります。", "이제 활에 시위가 필요합니다: 통나무에 칼을 쓰면 시위 없는 활(또는 전쟁활)이 되고, 시위를 걸면 완성. 깎은 보석에 시위를 꿰면 부적이 되고, 마법부여 주문은 월장석과 장미석 부적을 펜던트로 바꿉니다.", "弓现在需要弦了：用小刀加工原木得到未上弦的弓（或战弓），上弦即完成。在切割好的宝石上穿弦可做成护符，附魔法术可把月光石和玫瑰石护符变成吊坠。", "弓現在需要弦了：用小刀加工原木得到未上弦的弓（或戰弓），上弦即完成。在切割好的寶石上穿弦可做成護符，附魔法術可把月光石和玫瑰石護符變成吊墜。", "Cung giờ cần dây: dùng dao lên gỗ để gọt cung chưa căng dây (hoặc cung chiến), và một sợi dây hoàn thiện nó. Dây trên đá quý đã cắt làm thành bùa hộ mệnh, và phép Phù phép biến bùa đá mặt trăng và đá hồng thành mặt dây chuyền.", "Busur kini butuh tali: pisau pada kayu memotong busur tanpa tali (atau busur perang), dan tali menyelesaikannya. Tali pada permata potong menjadi jimat, dan mantra Pesona mengubah jimat batu bulan dan batu mawar menjadi liontin.", "ธนูตอนนี้ต้องมีสาย: ใช้มีดกับท่อนไม้ได้ธนูไม่มีสาย (หรือธนูศึก) แล้วใส่สายให้เสร็จ สายบนอัญมณีที่เจียแล้วเป็นเครื่องราง และคาถาเสริมพลังเปลี่ยนเครื่องรางมูนสโตนและหินกุหลาบเป็นจี้", "Yayların artık kirişe ihtiyacı var: kütüğe bıçak kirişsiz bir yay (ya da savaş yayı) keser, kiriş onu bitirir. Kesilmiş bir mücevhere kiriş geçirmek muska yapar ve Büyüleme büyüleri ay taşı ve gül taşı muskaları kolyeye çevirir.", "Los arcos necesitan cuerda: un cuchillo sobre troncos talla un arco sin encordar (o un arco de guerra), y una cuerda lo termina. Una cuerda en una gema tallada hace un amuleto, y los hechizos de Encantar convierten los amuletos de piedra lunar y piedra rosa en colgantes.", "Os arcos agora precisam de corda: uma faca nas toras corta um arco sem corda (ou arco de guerra), e uma corda o termina. Uma corda numa gema lapidada faz um amuleto, e os feitiços de Encantar transformam amuletos de pedra da lua e pedra-rosa em pingentes.", "Лукам теперь нужна тетива: нож по брёвнам вырезает лук без тетивы (или боевой лук), а тетива его завершает. Тетива на огранённом камне — это амулет, а заклинания Зачарования превращают амулеты из лунного и розового камня в подвески.", "Лукам тепер потрібна тятива: ніж по колодах вирізає лук без тятиви (або бойовий лук), а тятива його завершує. Тятива на огранованому камені — це амулет, а заклинання Зачарування перетворюють амулети з місячного й рожевого каменю на підвіски."],
};
